/* FIE V9.3.2 first-class D/ST intelligence.
 * Missing data remains missing, future weeks are labelled baseline estimates,
 * and every D/ST has a standard Overview + Weeks 1–18 drawer.
 */
(function(){
'use strict';
let bundle=null,loading=false,error=null,leagueKey=null,selectedWeek=null;
const $=id=>document.getElementById(id),safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>window.FIECore?.Numeric?.finiteOrNull?.(v)??null;
const f=(v,d=1)=>num(v)===null?'—':num(v).toFixed(d),signed=v=>num(v)===null?'—':`${num(v)>0?'+':''}${f(v)}`;
function lid(){return String(window.state?.league?.league_id||'');}
function week(){return Number(selectedWeek||window.currentWeek?.()||1);}
function season(){return window.FIECore?.SeasonResolver?.resolve?.()||Number(window.state?.league?.season)||new Date().getFullYear();}
function hasDST(){const c=window.FIELeagueContext?.current?.();return c?c.hasDST:(window.state?.league?.roster_positions||[]).some(x=>['DEF','DST'].includes(String(x).toUpperCase()));}
function format(){try{return String(window.activeFormatKey?.()||'REDRAFT')}catch{return'REDRAFT';}}
function rosterId(){return Number(window.state?.selectedRoster||0);}
function dstPlayers(){return (window.PLAYERS||[]).filter(p=>String(p.position||'').toUpperCase()==='DEF'&&p.leagueEligible!==false);}
function ownerStatus(p){if(Number(p.ownerRosterId)===rosterId()&&rosterId())return'Yours';if(p.availability==='FA'||p.ownerRosterId==null)return'FA';return p.owner||'Owned';}
function currentMap(){const m=new Map();for(const r of bundle?.players||[]){if(r.position_model!=='DEF')continue;for(const k of[r.sleeper_id,r.team,String(r.canonical_player_id||'').replace(/^DST:/,'')])if(k)m.set(String(k).toUpperCase(),r);}return m;}
function rowFor(p,m=currentMap()){return m.get(String(p.sleeperId||'').toUpperCase())||m.get(String(p.team||'').toUpperCase())||null;}
function currentProjection(p,r){return num(r?.decision_weekly_projection)??num(p.weeklyProjection)??num(p.sleeperWeeklyProjection);}
function currentRange(p,r){const lo=num(r?.p10),hi=num(r?.p90);if(lo!==null||hi!==null)return{low:lo,high:hi,source:'FIE empirical',estimate:false};const rr=window.FIEProjectionResolver?.range?.(p)||{};return{low:num(rr.low),high:num(rr.high),source:rr.source||'Unavailable',estimate:rr.estimate===true};}
function opponent(team,w){return window.FIESpecialTeamsSeries?.opponent?.(team,w,season())||'—';}
function rowWeek(p,r,w){const team=String(r?.team||p.team||p.sleeperId||'').toUpperCase(),opp=opponent(team,w),bye=opp==='BYE',cur=Number(w)===Number(bundle?.week||window.currentWeek?.()||1),published=cur?null:num(window.FIESpecialTeamsSeries?.sleeperProjection?.(p,w,season())),base=cur?currentProjection(p,r):(published??currentProjection(p,r)),rg=currentRange(p,r),mean=bye?0:base,low=bye?0:(published!==null?Math.max(0,published*.78):rg.low),high=bye?0:(published!==null?published*1.22:rg.high),source=bye?'Schedule':cur?(r?.projection_source||'Current-week baseline'):published!==null?`Sleeper Week ${w}`:'Baseline Estimate',estimate=!bye&&!cur;return{p,r,team,opp,mean,low,high,status:ownerStatus(p),active:cur&&r?.weekly_activation_eligible===true,source,estimate,bye,week:w};}
function decisionScore(x){const fmt=format(),fp=window.FIECore?.FormatRegistry?.profile?.(fmt)||{chopped:fmt.includes('CHOPPED'),bestBall:fmt.includes('BESTBALL')},mean=x.mean,p10=x.low,p90=x.high;if(mean===null)return-Infinity;if(fp.chopped&&fp.bestBall)return .565*mean+.21*(p10??mean)+.225*(p90??mean);if(fp.chopped)return .58*mean+.42*(p10??mean);if(fp.bestBall)return .55*mean+.45*(p90??mean);return mean;}
function boardForWeek(w=week()){const m=currentMap(),xs=dstPlayers().map(p=>rowWeek(p,rowFor(p,m),w)).filter(x=>x.team&&x.mean!==null);for(const x of xs)x.score=decisionScore(x);xs.sort((a,b)=>b.score-a.score);xs.forEach((x,i)=>x.rank=i+1);return xs;}
function replacement(xs){const svc=window.FIECore?.ReplacementService;if(!svc?.row||!xs.length)return null;const z=svc.row('DEF',xs.map(x=>({p:x.p,score:x.score,mean:x.mean})),'score',{league:state.league,state});return z?.row?xs.find(x=>x.p===z.row.p)||null:null;}
function next3(x){if(!x)return null;const vals=[];for(let w=x.week;w<=Math.min(18,x.week+2);w++){const row=boardForWeek(w).find(z=>z.team===x.team);if(row?.mean!==null)vals.push(row.mean);}return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;}
function action(x,xs){const bestFA=xs.find(z=>z.status==='FA'),mine=xs.find(z=>z.status==='Yours');if(x.bye)return'BENCH';if(x.status==='Yours'){if(bestFA&&bestFA.mean!==null&&x.mean!==null&&bestFA.mean-x.mean>=1.75)return'STREAM AWAY';return x.rank<=8?'START':'HOLD';}if(x.status!=='FA')return'OWNED';if(x.rank<=5&&(!mine||x.mean-(mine.mean??-999)>=1.25))return'STREAM';if(x.rank<=12)return'WATCH';return'AVOID';}
function ac(a){return/START|STREAM/.test(a)?'positive':/HOLD|WATCH|STASH/.test(a)?'score mid':'negative';}
function modelLabel(xs){const n=xs.filter(x=>x.active).length;if(n)return`${n}/32 FIE-active`;return xs.length?'Sleeper/baseline · FIE current validation gated or future estimate':'No D/ST projection rows';}
async function load(force=false){const k=lid();if(!k){bundle=null;return null;}if(!force&&bundle&&leagueKey===k)return bundle;if(loading)return bundle;loading=true;error=null;leagueKey=k;try{const rt=window.FIE_RESEARCH_RUNTIME,path=rt?.path?.('current/milestone5_current.json')||`data/research/leagues/${encodeURIComponent(k)}/current/milestone5_current.json`;const b=window.FIECurrentSnapshotStore?await window.FIECurrentSnapshotStore.load(path,{force}):await fetch(path).then(r=>{if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json();});if(String(b.league_id||'')!==k)throw new Error('League namespace mismatch');bundle=b;}catch(e){error=String(e?.message||e);bundle=null;}finally{loading=false;}return bundle;}
function openDrawer(x){const drawer=$('drawer'),body=$('drawerBody');if(!drawer||!body||!x)return;const xs=boardForWeek(x.week),repl=replacement(xs),rv=repl?.mean===null||repl?.mean===undefined?null:x.mean-(repl?.mean??0),stats=x.r?.predicted_stats||{};$('dTitle').textContent=`${x.team} D/ST`;$('dMeta').textContent=`D/ST · Season ${season()} · Week ${x.week} vs ${x.opp}`;$('dBadges').innerHTML=`<span class="pill">${safe(x.status)}</span><span class="pill">${safe(action(x,xs))}</span>${x.estimate?'<span class="pill">Estimate</span>':''}`;const weeks=[];for(let w=1;w<=18;w++){const b=boardForWeek(w),z=b.find(y=>y.team===x.team),rp=replacement(b),v=z&&rp?.mean!==null&&rp?.mean!==undefined?z.mean-rp.mean:null;if(z)weeks.push(`<tr><td>${w}</td><td>${safe(z.opp)}</td><td>${f(z.mean)}</td><td>${z.low===null&&z.high===null?'—':`${f(z.low)} / ${f(z.high)}`}</td><td>${signed(v)}</td><td>#${z.rank}</td><td>${safe(action(z,b))}</td><td>${safe(z.source)}</td><td>${z.estimate?'Estimate':z.active?'Governed/current':'Baseline'}</td></tr>`);}
  body.innerHTML=`<div class="fie93-drawer-tabs"><button class="btn primary" data-dst-tab="overview">Overview</button><button class="btn ghost" data-dst-tab="weeks">Weeks 1–18</button></div><div id="dstDrawerOverview"><div class="detail-grid"><div class="mini"><div class="m-label">Week projection</div><div class="m-value">${f(x.mean)}</div></div><div class="mini"><div class="m-label">Week rank</div><div class="m-value">#${x.rank}</div></div><div class="mini"><div class="m-label">vs replacement</div><div class="m-value">${signed(rv)}</div></div><div class="mini"><div class="m-label">Action</div><div class="m-value">${safe(action(x,xs))}</div></div></div><div class="notice"><b>Projection source:</b> ${safe(x.source)}${x.estimate?' · future-week baseline estimate':''}. Missing uncertainty data remains unavailable rather than being displayed as 0.</div><div class="metrics"><div class="metric"><span class="muted">Sacks</span><b>${f(stats.sack)}</b></div><div class="metric"><span class="muted">INT</span><b>${f(stats.int)}</b></div><div class="metric"><span class="muted">Fumble rec.</span><b>${f(stats.fum_rec)}</b></div><div class="metric"><span class="muted">D/ST TD</span><b>${f(stats.def_td)}</b></div><div class="metric"><span class="muted">Points allowed</span><b>${f(stats.points_allowed)}</b></div><div class="metric"><span class="muted">Low / High</span><b>${x.low===null&&x.high===null?'—':`${f(x.low)} / ${f(x.high)}`}</b></div></div></div><div id="dstDrawerWeeks" class="fie93-hidden"><div class="fie93-scroll"><table class="fie93-table"><thead><tr><th>Week</th><th>Opp</th><th>Projection</th><th>Low / High</th><th>vs Repl.</th><th>Rank</th><th>Action</th><th>Source</th><th>Confidence</th></tr></thead><tbody>${weeks.join('')}</tbody></table></div><div class="notice">Future weeks use clearly labelled baseline estimates until current-week Sleeper/FIE/schedule context becomes available. Verified byes are true zeroes; unknown schedules are not treated as byes.</div></div>`;body.querySelectorAll('[data-dst-tab]').forEach(b=>b.onclick=()=>{const ov=b.dataset.dstTab==='overview';$('dstDrawerOverview')?.classList.toggle('fie93-hidden',!ov);$('dstDrawerWeeks')?.classList.toggle('fie93-hidden',ov);body.querySelectorAll('[data-dst-tab]').forEach(x=>x.className=`btn ${x===b?'primary':'ghost'}`);});drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');}
function render(){const st=$('dstStatus'),box=$('dstSummary');if(!st||!box)return;if(!state.league){st.textContent='Load a Sleeper league first.';box.innerHTML='';return;}if(!hasDST()){st.textContent='This league does not roster a team D/ST, so D/ST intelligence is intentionally disabled.';box.innerHTML='';return;}if(selectedWeek===null)selectedWeek=Number(window.currentWeek?.()||1);if((!bundle||leagueKey!==lid())&&!loading){st.textContent='Loading league-specific D/ST snapshot…';load().then(()=>render());return;}if(loading){st.textContent='Loading league-specific D/ST snapshot…';return;}const xs=boardForWeek(),repl=replacement(xs);if(!xs.length){st.textContent=error?`D/ST snapshot unavailable: ${error}`:'No D/ST projections are available for this week.';box.innerHTML='';return;}const mine=xs.find(x=>x.status==='Yours'),bestFA=xs.find(x=>x.status==='FA');st.innerHTML=`<b>${safe(state.league.name||state.league.league_name||'Loaded league')}</b> · Season ${season()} · Week ${week()} · ${xs.length} D/ST · ${safe(modelLabel(xs))}.`;box.innerHTML=`<div class="fie93-filter-extra" style="margin-bottom:10px"><span class="filter-label">Week</span><select id="dstWeekSelect">${Array.from({length:18},(_,i)=>`<option value="${i+1}" ${week()===i+1?'selected':''}>${i+1}</option>`).join('')}</select></div><div class="intel-grid"><div class="intel-card"><span class="filter-label">Your D/ST</span><div class="big">${mine?safe(mine.team):'—'}</div><div class="tiny">${mine?`${f(mine.mean)} pts · #${mine.rank} · ${safe(action(mine,xs))}`:'No rostered D/ST'}</div></div><div class="intel-card"><span class="filter-label">Best available</span><div class="big">${bestFA?safe(bestFA.team):'—'}</div><div class="tiny">${bestFA?`${f(bestFA.mean)} pts · #${bestFA.rank}`:'No free agent'}</div></div><div class="intel-card"><span class="filter-label">Replacement line</span><div class="big">${repl?safe(repl.team):'—'}</div><div class="tiny">${repl?`${f(repl.mean)} pts · canonical cutoff`:''}</div></div></div><div class="table-wrap" style="margin-top:12px"><table class="m1-table fie93-table"><thead><tr><th>Rank</th><th>D/ST</th><th>Opp</th><th>Status</th><th>Week Proj</th><th>Low / High</th><th>vs Replacement</th><th>Next 3</th><th>Action</th></tr></thead><tbody>${xs.map(x=>{const a=action(x,xs),rv=repl?.mean===null||repl?.mean===undefined?null:x.mean-repl.mean,n3=next3(x);return`<tr data-dst-team="${safe(x.team)}"><td><b>#${x.rank}</b></td><td><b>${safe(x.team)}</b></td><td>${safe(x.opp)}</td><td>${safe(x.status)}</td><td><b>${f(x.mean)}</b>${x.estimate?' *':''}</td><td>${x.low===null&&x.high===null?'—':`${f(x.low)} / ${f(x.high)}${x.estimate?' *':''}`}</td><td>${signed(rv)}</td><td>${f(n3)}${x.week!==Number(bundle?.week)?' *':''}</td><td class="${ac(a)}"><b>${safe(a)}</b></td></tr>`;}).join('')}</tbody></table></div><div class="notice" style="margin-top:10px">* = future-week/baseline estimate. Missing ranges are shown as —, never fabricated 0. Click a D/ST for Overview and Weeks 1–18.</div>`;const sel=$('dstWeekSelect');if(sel)sel.onchange=()=>{selectedWeek=Number(sel.value);render();window.FIESpecialTeamsSeries?.preloadWeeks?.([selectedWeek,selectedWeek+1,selectedWeek+2],season()).then(()=>{if(Number(selectedWeek)===Number(sel.value))render();});};box.querySelectorAll('[data-dst-team]').forEach(tr=>tr.onclick=()=>openDrawer(xs.find(x=>x.team===tr.dataset.dstTeam)));}
function refresh(){bundle=null;leagueKey=null;return load(true).then(render);}
window.FIEDST={VERSION:'9.3.2',render,refresh,load,hasDST,board:boardForWeek,decisionScore,openDrawer};
})();
